{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Codeine, which shares the 3-methoxy-N-methyl morphinan scaffold with the query, has an absolute oral bioavailability of about 40% in postoperative patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a 14-hydroxy morphinan analogue, has an absolute oral bioavailability of 41% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a structurally related morphinan, has an absolute oral bioavailability of 30% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Naltrexone, the closest analogue by Morgan similarity, has oral bioavailability of about 5% in healthy volunteers due to extensive first-pass metabolism; this is contradictory evidence, but its N-cyclopropylmethyl and phenolic 3-OH groups differ from the query's N-methyl and 3-methoxy groups, reducing transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxycodone (3-methoxy-N-methyl-14-hydroxy-morphinan-6-one). Although the closest analogue naltrexone has low oral bioavailability, its liabilities (phenolic 3-OH and N-cyclopropylmethyl) are absent in the query. Multiple close morphinan analogues with 3-alkoxy/N-methyl or 14-hydroxy features (codeine, nalmefene, noscapine) show absolute oral bioavailability of 30-90%, and the physicochemical prior is favorable. Thus F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself in the provided evidence.",
    "Fasted-state conditions are not consistently specified for the supporting analogues; food effects could alter F.",
    "First-pass metabolism of the query is inferred from analogues rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

